/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const collabTaskDetails = api.state.collabTaskDetails;
	return (collabTaskDetails.channels && collabTaskDetails.channels.length > 0 && collabTaskDetails.channels[0].channelType && collabTaskDetails.channels[0].channelType.value === 'slack-channel-chat');
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const collabTaskDetails = api.state.collabTaskDetails;
    if (collabTaskDetails.channels && collabTaskDetails.channels.length > 0 && collabTaskDetails.channels[0].channelType && collabTaskDetails.channels[0].channelType.value === 'slack-channel-chat')
        return helpers.translateSync('Slack collaborations are only supported in the workbench.You can manage them there.');
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const collabTaskDetails = api.state.collabTaskDetails;
    return (collabTaskDetails && ((collabTaskDetails.commTaskType && collabTaskDetails.commTaskType.toUpperCase() == 'ACTIVE') || collabTaskDetails.isActive)) ? helpers.translateSync('In Progress') : helpers.translateSync('Pending');
}

